Definition align_up (al p : Z) : Z := Z.land ((p + al - 1) mod 2^64) ((- al) mod 2^64).
Definition align_d (al p : Z) : Z := (align_up al p - p) mod 2^64.
Definition std_align_res (al sz p spc : Z) : option (Z * Z) :=
  if spc <? sz then None
  else if spc - sz <? align_d al p then None
  else Some (align_up al p, spc - align_d al p).

Lemma align_up_range : forall al p, 0 <= align_up al p < 2^64.
Proof.
  intros al p. unfold align_up. apply Z_land_range; [apply Z.mod_pos_bound; lia| apply Z.mod_pos_bound; lia].
Qed.

