(* [comment removed for export] *)
Definition std_align_adj_post (ra sp gp tp s0 s1 a2 a3 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (al sz PA p spc : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a0 a1 a4 a5 a6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(PA, PA + 16)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ match std_align_res al sz p spc with
       | None => a0 = wz 0 /\ rw_cells asegs m' PA [C8 (wz p); C8 (wz spc)]
       | Some (a, spc') => a0 = wz a /\ rw_cells asegs m' PA [C8 (wz a); C8 (wz spc')]
       end.

Definition std_align_adj_stmt : Prop :=
  forall (al sz PA p spc : Z) ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  rw_cells asegs m PA [C8 (wz p); C8 (wz spc)] ->
  0 <= al < 2^64 -> 0 <= sz < 2^64 -> 0 <= p < 2^64 -> 0 <= spc < 2^64 ->
  mem_inv asegs m ->
  evt asegs (std_align_adj_post ra sp gp tp s0 s1 (wz PA) (wz (PA + 8)) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t0 t1 t2 t3 t4 t5 t6 F fc al sz PA p spc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz al) (wz sz) (wz PA) (wz (PA + 8)) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_STD_ALIGN) fc None m (seg_rom asegs)).

