        F (Z_to_bv 64 P_A_STRCMP) fc None m (seg_rom asegs)).
Proof.
  intros until m; intros IL IR L0 L1 R0 R1 NL NR <- MI.
  pose proof (ro_cells_bytes_at _ _ _ _ (ro_cells_image asegs m L _ MI IL L0 L1)) as BL.
  pose proof (ro_cells_bytes_at _ _ _ _ (ro_cells_image asegs m R _ MI IR R0 R1)) as BR.
  cbn [cells_bytes cbytes] in BL, BR. rewrite app_nil_r in BL, BR.
  apply strcmp_spec; assumption.
Qed.

